const replicas = 40;
const poolPerReplica = 25;
const maxConnections = 200;
const mbPerBackend = 10;

const requested = replicas * poolPerReplica;
const granted = Math.min(requested, maxConnections);
const rejected = requested - granted;
const ramMB = granted * mbPerBackend;

console.log('requested=' + requested);
console.log('granted=' + granted);
console.log('rejected=' + rejected);
console.log('backend_ram_MB=' + ramMB);
